mapper.update:
UPDATE textbook_web_pages
   SET latest_revision_id = COALESCE(#{latestRevisionId}, latest_revision_id),
       last_fetch_status = #{status}, last_fetched_at = #{fetchedAt}
 WHERE page_id = #{pageId}

mapper.select:
SELECT r.*, p.url, p.site, p.cache_scope_key
  FROM textbook_web_revisions r JOIN textbook_web_pages p ON p.page_id = r.page_id
 WHERE r.page_id = #{pageId} AND r.content_hash = #{contentHash} AND r.parser_version = #{parserVersion}
